<?php require 'config/functions.php';
$counts=[]; foreach (['produtos','enderecos','transportadores','fretes'] as $t) $counts[$t]=(int)$pdo->query("SELECT COUNT(*) FROM $t")->fetchColumn();
$recent=$pdo->query("SELECT f.id,f.data_frete,f.status,t.nome AS transportador FROM fretes f JOIN transportadores t ON t.id=f.transportador_id ORDER BY f.id DESC LIMIT 5")->fetchAll();
require 'header.php'; ?>
<section class="hero"><div class="eyebrow mb-2">MR GESTÃO LOGÍSTICA</div><h1>Olá! Bem-vindo ao sistema.</h1><p class="text-secondary">Escolha uma função para começar. Os módulos estão organizados para acompanhar sua operação.</p></section>
<div class="row g-3 mb-4"><?php foreach ([['produtos','01','Produtos','Cadastre os itens que serão transportados.','produtos.php'],['enderecos','02','Endereços','Organize os locais de origem e destino.','enderecos.php'],['transportadores','03','Transportadores','Gerencie quem realiza as entregas.','transportadores.php'],['fretes','04','Fretes','Monte fretes com um ou vários produtos.','fretes.php']] as $m): ?><div class="col-md-6"><div class="tile"><div class="number"><?= $m[1] ?></div><h3><?= $m[2] ?></h3><p><?= $m[3] ?></p><a href="<?= $m[4] ?>">Abrir módulo →</a></div></div><?php endforeach; ?></div>
<h2 class="h5 fw-bold mb-3">Resumo da operação</h2><div class="row g-3 mb-4"><?php foreach (['produtos'=>'Produtos','enderecos'=>'Endereços','transportadores'=>'Transportadores','fretes'=>'Fretes'] as $key=>$label): ?><div class="col-6 col-lg-3"><div class="stat"><small><?= $label ?></small><strong><?= $counts[$key] ?></strong></div></div><?php endforeach; ?></div>
<div class="panel mb-4"><h2 class="h5 fw-bold mb-3">Fretes recentes</h2><?php if (!$recent): ?><p class="text-secondary mb-0">Nenhum frete cadastrado ainda.</p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Nº</th><th>Data</th><th>Transportador</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td>#<?= $r['id'] ?></td><td><?= date('d/m/Y',strtotime($r['data_frete'])) ?></td><td><?= h($r['transportador']) ?></td><td><span class="badge-soft"><?= h($r['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
